def f(g):
    h,w=len(g),len(g[0]); o=[c for c in set(sum(g,[])) if c!=8]
    out=[row[:] for row in g]
    for ci in o:
        # find cells of color ci not connected (8-conn) to any ci cell... actually filled holes inside frames
        seen=set(); stack=[]
        for i in range(h):
            for j in range(w):
                if g[i][j]==ci and (i,j) not in seen:
                    seen.add((i,j)); stack=[(i,j)]
                    while stack:
                        a,b=stack.pop()
                        for da in(-1,0,1):
                            for db in(-1,0,1):
                                p,q=a+da,b+db
                                if 0<=p<h and 0<=q<w and g[p][q]==ci and (p,q) not in seen:
                                    seen.add((p,q)); stack.append((p,q))
        holes=set()
        for i in range(h):
            for j in range(w):
                if g[i][j]!=ci:
                    # BFS through non-ci region around
                    if all(out[a][b]!=ci for a in range(max(0,i-1),min(h,i+2)) for b in range(max(0,j-1),min(w,j+2))) or True:
                        pass
                    # check if surrounded by ci (8-neighborhood mostly ci or frame)
                    nb=[g[a][b] for a in range(i-1,i+2) for b in range(j-1,j+2) if (a,b)!=(i,j) and 0<=a<h and 0<=b<w]
                    if len(nb)==8 and sum(n==ci for n in nb)==8:
                        continue
                    # hole: neighbors are frame(8) or ci
                    nframe=sum(n==8 for n in nb); nci=sum(n==ci for n in nb)
                    if nci>=6 and nframe>=2:
                        holes.add((i,j))
        for (i,j) in holes: out[i][j]=ci
    return out
